  "description": "Compare average goals scored by home and away teams.",
  "data": {
    "url": "/results.csv"
  },
  "transform": [
    {
      "fold": ["home_score", "away_score"],
      "as": ["team_type", "score"]
    },
    {
      "aggregate": [
        {
          "op": "mean",
          "field": "score",
          "as": "avg_score"
        }
      ],
      "groupby": ["team_type"]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "team_type",
      "type": "nominal",
      "title": "Team Type",
      "axis": {
        "labelExpr": "datum.value == 'home_score' ? 'Home Team' : 'Away Team'"
      }
    },
    "y": {
      "field": "avg_score",
      "type": "quantitative",
      "title": "Average Goals"
    },
    "color": {
      "field": "team_type",
      "type": "nominal",
      "scale": {
        "domain": ["home_score", "away_score"],
        "range": ["#1f77b4", "#ff7f0e"]
      },
      "legend": null
    }
  },
  "title": {
    "text": "Average Goals: Home Team vs Away Team",
    "subtitle": "Home teams generally score more goals on average than away teams."
  }
}

